namespace ExpenseTracker.Models;

public class Expense
{
    public string Category { get; }
    public int Amount { get; }

    public Expense(string category, int amount)
    {
        Category = category;
        Amount = amount;
    }

    public string Describe() => $"{Category}: {Amount} руб.";
}

ExpenseTracker/Program.cs:
using ExpenseTracker.Models;
using ExpenseTracker.Reports;

Expense[] expenses = new Expense[]
{
    new Expense("Еда", 120),
    new Expense("Транспорт", 80)
};
Console.WriteLine($"Итого: {ExpenseReport.Total(expenses)} руб.");

ExpenseTracker/Reports/ExpenseReport.cs:
using ExpenseTracker.Models;

namespace ExpenseTracker.Reports;

public static class ExpenseReport
{
    public static int Total(Expense[] expenses)
    {
        int total = 0;
        foreach (Expense expense in expenses)
            total += expense.Amount;
        return total;
    }
}
